#!/usr/bin/env python3
"""Compute deterministic numeric ground truth for CSX-287_Q2."""

from __future__ import annotations

import json
from datetime import date
from pathlib import Path

try:
    from PIL import Image
except ImportError as exc:  # pragma: no cover
    raise SystemExit("Pillow is required to compute image pixel statistics") from exc


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-287"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_August_2023_Central_Chile_atmospheric_rivers.json",
    "data/physical_hazard/physical_hazard_003_NASA_POWER_daily_point_sample.json",
    "data/physical_hazard/physical_hazard_004_Open-Meteo_archive_point_sample.json",
    "data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_007_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_009_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json",
    "data/remote_sensing/remote_sensing_005_pre.jpg",
    "data/remote_sensing/remote_sensing_006_event.jpg",
]


def read_json(rel_path: str) -> dict:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig"))


def rounded(value: float, digits: int) -> float:
    return float(f"{value:.{digits}f}")


def rgb_pixels(image: Image.Image) -> list[tuple[int, int, int]]:
    provider = getattr(image, "get_flattened_data", None)
    data = provider() if callable(provider) else image.getdata()
    values = list(data)
    if not values:
        return []

    first = values[0]
    if isinstance(first, (tuple, list)):
        return [(int(pixel[0]), int(pixel[1]), int(pixel[2])) for pixel in values]

    if len(values) % 3 != 0:
        raise ValueError("RGB pixel byte stream length is not divisible by 3")
    return [
        (int(values[index]), int(values[index + 1]), int(values[index + 2]))
        for index in range(0, len(values), 3)
    ]


def image_fraction_stats(rel_path: str) -> dict[str, float]:
    with Image.open(PACKAGE_DIR / rel_path) as source:
        image = source.convert("RGB")
    pixels = rgb_pixels(image)
    count = len(pixels)
    if count == 0:
        raise ValueError(f"image has no pixels: {rel_path}")
    bright = sum(1 for red, green, blue in pixels if (red + green + blue) / 3 > 180)
    blue_dominant = sum(
        1 for red, green, blue in pixels if blue > red + 20 and blue > green + 10
    )
    return {
        "bright_fraction": bright / count,
        "blue_fraction": blue_dominant / count,
    }


def local_precip_series() -> dict[str, list[float]]:
    power = read_json("data/physical_hazard/physical_hazard_003_NASA_POWER_daily_point_sample.json")
    open_meteo = read_json("data/physical_hazard/physical_hazard_004_Open-Meteo_archive_point_sample.json")
    return {
        "nasa_power_mm": [
            float(value) for value in power["properties"]["parameter"]["PRECTOTCORR"].values()
        ],
        "open_meteo_mm": [float(value) for value in open_meteo["daily"]["precipitation_sum"]],
    }


def regional_mean_precip() -> dict[str, float]:
    era5 = read_json("data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json")
    gpm = read_json("data/physical_hazard/physical_hazard_007_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json("data/physical_hazard/physical_hazard_009_CHIRPS_daily_event_accumulated_precipitation.json")
    return {
        "era5_land": float(era5["stats"]["precipitation_sum_mm_mean"]),
        "gpm_imerg": float(gpm["stats"]["gpm_event_precip_mm_mean"]),
        "chirps": float(chirps["stats"]["chirps_event_precip_mm_mean"]),
    }


def main() -> None:
    metadata = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_August_2023_Central_Chile_atmospheric_rivers.json"
    )
    alpha = read_json(
        "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json"
    )

    start = date.fromisoformat(anchor["temporal_window"]["start_date"])
    end = date.fromisoformat(anchor["temporal_window"]["end_date"])
    event_span_days = (end - start).days + 1

    local_series = local_precip_series()
    local_totals = {name: sum(values) for name, values in local_series.items()}
    local_total_mean = sum(local_totals.values()) / len(local_totals)
    local_max_daily = max(max(values) for values in local_series.values())
    heavy_day_count = min(sum(1 for value in values if value >= 10) for values in local_series.values())
    heavy_day_fraction = heavy_day_count / event_span_days

    regional_means = regional_mean_precip()
    regional_mean_max = max(regional_means.values())
    point_to_regional_ratio = local_total_mean / regional_mean_max

    pre_image = image_fraction_stats("data/remote_sensing/remote_sensing_005_pre.jpg")
    event_image = image_fraction_stats("data/remote_sensing/remote_sensing_006_event.jpg")
    bright_fraction_delta = event_image["bright_fraction"] - pre_image["bright_fraction"]
    blue_fraction_delta = event_image["blue_fraction"] - pre_image["blue_fraction"]
    image_shift_index = (
        abs(bright_fraction_delta) / 0.05 + abs(blue_fraction_delta) / 0.02
    ) / 2

    annual_change_mean = float(alpha["stats"]["alphaearth_1_minus_cosine_mean"])
    annual_change_max = float(alpha["stats"]["alphaearth_1_minus_cosine_max"])

    components_raw = {
        "total_c": min(local_total_mean / 100, 1),
        "peak_c": min(local_max_daily / 50, 1),
        "persistence_c": heavy_day_fraction,
        "scale_c": min(point_to_regional_ratio / 10, 1),
        "image_c": 1 - min(image_shift_index, 1),
        "annual_c": 1 - min(annual_change_mean / 0.10, 1),
    }
    rainfall_scale_score_raw = (
        0.25 * components_raw["total_c"]
        + 0.20 * components_raw["peak_c"]
        + 0.15 * components_raw["persistence_c"]
        + 0.20 * components_raw["scale_c"]
        + 0.10 * components_raw["image_c"]
        + 0.10 * components_raw["annual_c"]
    )

    anchors = {
        "event_span_days": event_span_days,
        "local_total_mean_mm": rounded(local_total_mean, 1),
        "local_max_daily_mm": rounded(local_max_daily, 1),
        "heavy_day_fraction": rounded(heavy_day_fraction, 3),
        "regional_mean_max_mm": rounded(regional_mean_max, 3),
        "point_to_regional_ratio": rounded(point_to_regional_ratio, 3),
        "image_shift_index": rounded(image_shift_index, 3),
        "annual_change_mean": rounded(annual_change_mean, 4),
    }
    components = {name: rounded(value, 3) for name, value in components_raw.items()}
    rainfall_scale_score = rounded(rainfall_scale_score_raw, 3)
    class_label = (
        "localized_persistent_rainfall_dominant"
        if rainfall_scale_score >= 0.80 and anchors["heavy_day_fraction"] == 1.0
        else "mixed_or_surface_change_dominant"
    )

    output = {
        "schema_version": "1.0",
        "task_id": "CSX-287_Q2",
        "event_id": "CSX-287",
        "task_type": "numeric",
        "task_subtype": "rainfall_scale_surface_change_threshold_ledger",
        "target_family": "central_chile_rainfall_scale_surface_consistency_ledger",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "event": {
            "event_name": metadata["event_name"],
            "event_date_or_span": f"{start.isoformat()} to {end.isoformat()}",
            "region": "Central Chile",
        },
        "primary_gt": {
            "answer": rainfall_scale_score,
            "rainfall_scale_score": rainfall_scale_score,
            "class_label": class_label,
            "anchors": anchors,
            "components": components,
            "formula": "0.25*total_c+0.20*peak_c+0.15*persistence_c+0.20*scale_c+0.10*image_c+0.10*annual_c",
            "threshold": "score>=0.80 and heavy_day_fraction==1.0",
            "tolerance": 0.005,
        },
        "key_values": {
            "local_point_series_mm": {
                name: [rounded(value, 2) for value in values]
                for name, values in local_series.items()
            },
            "local_total_mm": {name: rounded(value, 1) for name, value in local_totals.items()},
            "regional_mean_precip_mm": {
                name: rounded(value, 3) for name, value in regional_means.items()
            },
            "image_fractions": {
                "pre_bright": rounded(pre_image["bright_fraction"], 6),
                "event_bright": rounded(event_image["bright_fraction"], 6),
                "bright_delta": rounded(bright_fraction_delta, 6),
                "pre_blue": rounded(pre_image["blue_fraction"], 6),
                "event_blue": rounded(event_image["blue_fraction"], 6),
                "blue_delta": rounded(blue_fraction_delta, 6),
            },
            "annual_change": {
                "mean": rounded(annual_change_mean, 6),
                "max": rounded(annual_change_max, 6),
                "max_to_mean": rounded(annual_change_max / annual_change_mean, 3),
            },
            "threshold_flags": {
                "score_ge_0_80": rainfall_scale_score >= 0.80,
                "heavy_day_fraction_eq_1": anchors["heavy_day_fraction"] == 1.0,
            },
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "local_rainfall_extraction",
                    "points": 4,
                    "description": "Computes the inclusive four-day span, both local point totals, their 120.7 mm mean, and the 54.5 mm daily maximum.",
                    "partial_credit": "Credit correct series extraction with small rounding errors or one missing local aggregate.",
                },
                {
                    "name": "persistence_fraction",
                    "points": 4,
                    "description": "Counts days at or above 10 mm in both local series and computes the conservative fraction as 1.000.",
                    "partial_credit": "Credit correct heavy-day counting for one series or a correct numerator with an incorrect span.",
                },
                {
                    "name": "regional_scale_ratio",
                    "points": 3,
                    "description": "Extracts the three regional mean precipitation values, uses 8.871 mm as the maximum, and computes the 13.606 point-to-regional ratio.",
                    "partial_credit": "Credit correct regional extraction or a correct ratio formula with minor rounding drift.",
                },
                {
                    "name": "image_and_annual_terms",
                    "points": 3,
                    "description": "Computes the image-shift index of 0.651 from all RGB pixels in the package JPEG images as delivered, and extracts annual_change_mean of 0.0611.",
                    "partial_credit": "Credit correct image fractions or annual extraction when the combined image index is incomplete.",
                },
                {
                    "name": "component_score",
                    "points": 4,
                    "description": "Applies all capped component formulas and the weighted sum to reach rainfall_scale_score 0.874 within 0.005.",
                    "partial_credit": "Credit a correct component ledger with an arithmetic slip in the weighted sum.",
                },
                {
                    "name": "json_result",
                    "points": 2,
                    "description": "Returns compact JSON containing anchors, components, the score, and the class label localized_persistent_rainfall_dominant.",
                    "partial_credit": "Credit the correct score and class when the JSON shape needs minor cleanup.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
        "supporting_metrics": {
            "image_method": {
                "pixel_scope": "all RGB pixels in each package JPEG image as delivered",
                "no_data_handling": "no separate no-data mask is applied to the JPEG browse images",
                "bright_fraction_rule": "mean RGB brightness > 180",
                "blue_fraction_rule": "B > R + 20 and B > G + 10",
            }
        },
    }

    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(output, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
